namespace RonSijm.FluidHumidifier.Factories.MediaConnect;

public class RouterInputFactory(string resourceName = null, Action<Humidifier.MediaConnect.RouterInput> factoryAction = null) : ResourceFactory<Humidifier.MediaConnect.RouterInput>(resourceName)
{

    internal InnerRouterInputRouterContentQualityAnalysisConfigurationFactory ContentQualityAnalysisConfigurationFactory { get; set; }

    internal InnerRouterInputRouterInputTransitEncryptionFactory TransitEncryptionFactory { get; set; }

    internal InnerRouterInputRouterInputConfigurationFactory ConfigurationFactory { get; set; }

    internal InnerRouterInputMaintenanceConfigurationFactory MaintenanceConfigurationFactory { get; set; }

    protected override Humidifier.MediaConnect.RouterInput Create()
    {
        var routerInputResult = CreateRouterInput();
        factoryAction?.Invoke(routerInputResult);

        return routerInputResult;
    }

    private Humidifier.MediaConnect.RouterInput CreateRouterInput()
    {
        var routerInputResult = new Humidifier.MediaConnect.RouterInput
        {
            GivenName = InputResourceName,
        };

        return routerInputResult;
    }
    public override void CreateChildren(Humidifier.MediaConnect.RouterInput result)
    {
        base.CreateChildren(result);

        result.ContentQualityAnalysisConfiguration ??= ContentQualityAnalysisConfigurationFactory?.Build();
        result.TransitEncryption ??= TransitEncryptionFactory?.Build();
        result.Configuration ??= ConfigurationFactory?.Build();
        result.MaintenanceConfiguration ??= MaintenanceConfigurationFactory?.Build();
    }

} // End Of Class

